WITH latest_match AS (SELECT s.*, latest.inventory_quantity, latest.inventory_last_restock FROM products s JOIN LATERAL (SELECT c.quantity AS inventory_quantity, c.last_restock AS inventory_last_restock FROM inventory c WHERE c.product_id = s.id AND c.last_restock <= s.launch_date ORDER BY c.last_restock DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT brand, category, supplier_id, PERCENTILE_APPROX(price, 0.5) AS price_p50, PERCENTILE_APPROX(inventory_quantity, 0.9) AS inventory_quantity_p90, BIT_OR(stock_qty) AS stock_qty_bit_or, COUNT(*) FILTER (WHERE category = 'Books') AS books_rows FROM latest_match GROUP BY GROUPING SETS ((brand, category, supplier_id), (brand, category), (brand))
